UPDATE route_waypoints rw
   SET link_kind = 'waypoint', link_kind_at = NOW()
  FROM pairs
 WHERE rw.route_id::text = pairs.route_id::text
   AND rw.place_id::text = pairs.place_id::text
   AND rw.link_kind = 'nearby';

